  'De afbeelding gaat ongewijzigd naar':
      'A kép változatlanul ide kerül elküldésre:',
  'OciDeck lakt niets weg in een afbeelding: gezichten, tekst op een schermafdruk en gegevens in beeld gaan mee.':
      'Az OciDeck semmit sem takar ki a képen: az arcok, a képernyőkép szövege és a látható adatok is elmennek.',
  'De beeldcontrole vond hier een of meer herkenbare gezichten.':
      'A képellenőrzés egy vagy több felismerhető arcot talált itt.',
  'Naast de export komen twee bestanden te staan waarmee een ontvanger de redacties kan natrekken.':
      'Az exportálás mellé két fájl kerül, amelyekkel a címzett ellenőrizheti a kitakarásokat.',
  'somt op wat er is weggelaten, zonder de waarden zelf. Dit bestand mag met het rapport mee.':
      'felsorolja, mi maradt ki, maguk az értékek nélkül. Ez a fájl mehet a jelentéssel együtt.',
  'bevat de sleutels waarmee elke weggelakte waarde is terug te rekenen. Stuur dit bestand niet mee: dan is de redactie ongedaan gemaakt. Bewaar het bij de bron.':
      'tartalmazza a kulcsokat, amelyekkel minden kitakart érték visszaszámítható. Ezt a fájlt ne küldje el: ezzel a kitakarás érvényét veszti. Tartsa a forrás mellett.',
  'slides': 'dia',
  'Achtergehouden': 'Visszatartva',
  'Achtergehouden: strenger geclassificeerd dan de presentatie':
      'Visszatartva: szigorúbb besorolású, mint a prezentáció',
  '1 slide achtergehouden door haar TLP': '1 dia visszatartva a TLP-je miatt',
  'slides achtergehouden door hun TLP': 'dia visszatartva a TLP-jük miatt',
  'Deze slides gaan niet mee bij presenteren, exporteren of in het pakket. Verhoog het TLP-niveau van de presentatie bij Presentatie-info om ze mee te nemen.':
      'Ezek a diák nem kerülnek bele a bemutatóba, az exportba, sem a csomagba. Emeld meg a prezentáció TLP-szintjét a Prezentáció adatainál, hogy bekerüljenek.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Minden dia vissza van tartva a TLP-besorolása miatt – nincs mit megjeleníteni.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Minden dia vissza van tartva a TLP-besorolása miatt – nincs mit exportálni.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Minden dia ki van hagyva vagy vissza van tartva a TLP-besorolása miatt – nincs mit megjeleníteni.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Minden dia ki van hagyva vagy vissza van tartva a TLP-besorolása miatt – nincs mit exportálni.',
  'Grafiekcijfers zijn niet opgeslagen — ze staan alleen nog in dit venster:':
      'A diagramok számai nem lettek elmentve — már csak ebben az ablakban léteznek:',
  'In de browser is er geen crashherstel: sluit je dit tabblad, dan is niet-opgeslagen werk weg. Sla je presentatie zelf op.':
      'A böngészőben nincs összeomlás utáni helyreállítás: ha bezárod ezt a lapot, a nem mentett munka elvész. Mentsd el magad a prezentációdat.',
  '•  De lokale CVE-database (je start de download zelf): OciDeck haalt de bulkgegevens op via api.github.com en het releasebestand waar dat adres naar wijst.':
      '•  A helyi CVE-adatbázis (a letöltést Ön indítja): az OciDeck a tömeges adatokat az api.github.com címen és az arra mutató kiadási fájlon keresztül tölti le.',
  '•  CVE opzoeken (staat standaard uit): staat het aan, dan gaat je zoekterm naar de ingestelde CVE-spiegel en, als die niets vindt, naar de Europese database van ENISA en naar MITRE.':
      '•  CVE-keresés (alapértelmezetten kikapcsolva): ha be van kapcsolva, a keresőkifejezés a beállított CVE-tükörhöz kerül, és ha az nem talál semmit, az ENISA európai adatbázisához és a MITRE-hez.',
  '•  Een ingesloten YouTube- of Vimeo-video laadt de speler bij die dienst.':
      '•  A beágyazott YouTube- vagy Vimeo-videó a lejátszót az adott szolgáltatástól tölti be.',
  '•  In de browser: weigert de browser een adres rechtstreeks op te halen, dan probeert OciDeck het via de server waar de app vandaan komt; dat adres komt dan bij die server terecht.':
      '•  A böngészőben: ha a böngésző megtagadja egy cím közvetlen letöltését, az OciDeck újra próbálja azon a kiszolgálón keresztül, ahonnan az alkalmazás érkezett; így az a cím eljut arra a kiszolgálóra.',
  'Intrekken is niet vastgelegd. Bij de volgende start geldt uw toestemming weer.':
      'A visszavonás nem lett elmentve. A következő indításkor a hozzájárulása ismét érvényes lesz.',
  'Een tussenkop die een nieuw deel van de presentatie aankondigt. Houd het kort. Voeg via de afbeeldingsbibliotheek een achtergrondbeeld toe.':
      'Szakaszcím, amely a bemutató új részét jelzi. Tartsd röviden. Adj hozzá háttérképet a képtárból.',
  'Bronnen doorzoeken…': 'Keresés a forrásokban…',
  'Niet doorzocht': 'Nem átvizsgálva',
  'Deze controle draait niet in de webversie: gezichtsherkenning vergt een systeembibliotheek die de browser niet heeft. Gebruik de desktopversie om afbeeldingen op gezichten na te kijken.':
      'Ez az ellenőrzés nem fut a webes verzióban: az arcfelismeréshez egy rendszerkönyvtár kell, amely a böngészőből hiányzik. A képek arcokra való ellenőrzéséhez használd az asztali verziót.',
  'Het token heeft lees- en schrijfrechten op de repository nodig. Gitea en Forgejo kennen geen server-side zoeken; OciDeck zoekt lokaal.':
      'A tokennek olvasási és írási hozzáférés kell a tárolóhoz. A Gitea és a Forgejo nem tud kiszolgálóoldali keresést; az OciDeck helyben keres.',
  'Het token heeft de repo-scope nodig (of fijnmazig: Contents lezen en schrijven).':
      'A tokennek a repo hatókör kell (vagy finomhangolva: Contents olvasás és írás).',
  'Het token heeft read_repository, write_repository en read_api nodig. Server-side zoeken vereist Advanced- of Exact Search.':
      'A tokennek read_repository, write_repository és read_api kell. A kiszolgálóoldali kereséshez Advanced vagy Exact Search szükséges.',
  'Snelle server-zoekopdracht — door indexeringsvertraging kan een net gewijzigd deck ontbreken.':
      'Gyors kiszolgálóoldali keresés — az indexelési késés miatt egy nemrég módosított pakli hiányozhat.',
  'Media blijft niet bewaard in een los .md-bestand':
      'A médiatartalom nem marad meg egy egyszerű .md fájlban',
  'Afbeeldingen, video en audio die je in dit tabblad koos, leven alleen in het geheugen. Een los .md-bestand bewaart ze niet — bij heropenen zijn ze weg. Exporteer als .ocideck-pakket om het beeld mee te nemen.':
      'Az ezen a lapon kiválasztott képek, videó és hang csak a memóriában léteznek. Egy egyszerű .md fájl nem őrzi meg őket — újranyitáskor eltűnnek. Exportáld .ocideck csomagként, hogy magaddal vidd a médiát.',
  'Media verwijderd om privacyredenen':
