      'születési dátum, irányítószám és nem együtt — ez a három rendszerint egyetlen személyre mutat, név nélkül is',
  'Het certificaat van deze server wordt niet vertrouwd. Bij een zelf gehoste server kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Ennek a kiszolgáló tanúsítványa nem megbízható. Saját üzemeltetésű kiszolgáló esetén megtekintheted és megbízhatsz benne a Beállítások → Tárhely alatt.',
  'Het certificaat van de forge wordt niet vertrouwd. Bij een zelf gehoste forge kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Ennek a forge tanúsítványa nem megbízható. Saját üzemeltetésű forge esetén megtekintheted és megbízhatsz benne a Beállítások → Tárhely alatt.',
  'Het certificaat van het endpoint wordt niet vertrouwd. Bij een zelf gehost endpoint kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Ennek a endpoint tanúsítványa nem megbízható. Saját üzemeltetésű endpoint esetén megtekintheted és megbízhatsz benne a Beállítások → Tárhely alatt.',
  'Het certificaat van de forge wordt niet vertrouwd — zelfondertekend, verlopen, of op een andere naam gesteld.':
      'A forge tanúsítványa nem megbízható — önaláírt, lejárt, vagy más névre szól.',
  'Het certificaat van het endpoint wordt niet vertrouwd — zelfondertekend, verlopen, of op een andere naam gesteld.':
      'A endpoint tanúsítványa nem megbízható — önaláírt, lejárt, vagy más névre szól.',
  'creditcardnummer': 'bankkártyaszám',
  'beveiligingscode van een creditcard': 'kártya biztonsági kódja (CVV)',
  'gegevens in de sprekersnotities — onzichtbaar op de slide, wél in de export':
      'adatok az előadói jegyzetekben — a dián nem látszanak, az exportban igen',
  'Certificaat vertrouwen?': 'Megbízol ebben a tanúsítványban?',
  'Het certificaat van deze server is niet ondertekend door een erkende uitgever. Dat is gewoon bij een zelf gehoste server, maar het is ook hoe een afgeluisterde verbinding eruitziet.':
      'Ennek a kiszolgálónak a tanúsítványát nem elismert kibocsátó írta alá. Saját üzemeltetésű kiszolgálónál ez normális, de egy lehallgatott kapcsolat is így néz ki.',
  'Vergelijk de vingerafdruk hieronder met wat je server zelf toont. Komen ze overeen, dan praat je met de juiste machine.':
      'Hasonlítsd össze az alábbi ujjlenyomatot azzal, amit a kiszolgálód mutat. Ha egyeznek, a megfelelő géppel beszélsz.',
  'Uitgegeven aan': 'Kiállítva neki',
  'Uitgegeven door': 'Kibocsátó',
  'Geldig tot': 'Érvényes eddig',
  'Vingerafdruk (SHA-256)': 'Ujjlenyomat (SHA-256)',
  'Alleen dit ene certificaat wordt vertrouwd. Vervangt de server het later, dan vraagt OciDeck het opnieuw.':
      'Csak ez az egy tanúsítvány megbízható. Ha a kiszolgáló később lecseréli, az OciDeck újra rákérdez.',
  'Vertrouwen': 'Megbízom',
  'Certificaat bekijken': 'Tanúsítvány megtekintése',
  'De plekken waar je presentaties bewaart en doorzoekt — mappen op deze computer, WebDAV-servers, S3-buckets en git-repositories door elkaar. Sleep ze in de volgorde die jij wilt: de bovenste van een soort geldt als standaard.':
      'A helyek, ahol a prezentációidat tárolod és keresed — mappák ezen a számítógépen, WebDAV-kiszolgálók, S3-bucketek és git-repozitóriumok vegyesen. Húzd őket olyan sorrendbe, amilyet szeretnél: a fajtájában legfelső számít alapértelmezettnek.',
  '•  S3-opslag: verbind je met een bucket, dan worden het endpoint, de bucketnaam en je toegangssleutel bewaard (de geheime sleutel veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die opslagdienst verstuurd.':
      '•  S3-tároló: amikor csatlakozol egy buckethez, elmentődik a végpont, a bucket neve és a hozzáférési kulcsod (a titkos kulcs biztonságosan a rendszered kulcstartójában), és a prezentációk, amelyeket megnyitsz vagy mentesz, elküldődnek arra a tárolószolgáltatásra.',
  '•  Git-opslag: verbind je met een repository, dan wordt je toegangstoken bewaard (veilig in de sleutelbos van je systeem) en worden de presentaties die je opslaat als commits naar die server verstuurd. Een werkkopie van de repository blijft onversleuteld op dit apparaat staan.':
      '•  Git-tároló: amikor csatlakozol egy repozitóriumhoz, elmentődik a hozzáférési tokened (biztonságosan a rendszered kulcstartójában), és a prezentációk, amelyeket mentesz, commitként elküldődnek arra a kiszolgálóra. A repozitórium munkamásolata titkosítatlanul marad ezen az eszközön.',
  'Voor de taal van dit deck ontbreken de ziekte- en aandoeningsnamen. Religie, politieke overtuiging en vakbondstermen worden wel herkend, en controlegetallen (BSN, IBAN, paspoort) werken altijd — maar reken er niet op dat een diagnose gevonden wordt.':
      'Ennek a bemutatónak a nyelvéhez hiányoznak a betegségnevek. A vallás, a politikai vélemény és a szakszervezeti kifejezések felismerhetők, és az ellenőrző számjegyes minták (adóazonosító, IBAN, útlevél) mindig működnek — de ne számítson arra, hogy egy diagnózist megtalál.',
  'niet getest': 'nincs tesztelve',
  'Werkte op': 'Működött ekkor:',
  'Je bent aangemeld, maar hebt hier geen toegang. Je wachtwoord is niet het probleem — vraag de beheerder om rechten op deze map.':
      'Be vagy jelentkezve, de itt nincs hozzáférésed. Nem a jelszó a gond — kérj jogosultságot az adminisztrátortól ehhez a mappához.',
  'Je token is geldig, maar mag dit niet. Geef het meer rechten, of wacht als de forge een limiet oplegt.':
      'A tokened érvényes, de ehhez nincs joga. Adj neki több jogosultságot, vagy várj, ha a forge korlátot alkalmaz.',
  'Het token is geldig, maar mag dit niet — geef het meer rechten op de repository.':
      'A token érvényes, de ehhez nincs joga — adj neki több jogosultságot a tárolón.',
  'Aangemeld, maar geen toegang — je wachtwoord is niet het probleem. Vraag rechten op deze map.':
      'Bejelentkezve, de nincs hozzáférés — nem a jelszó a gond. Kérj jogosultságot ehhez a mappához.',
  'Dit lijkt een volledige DAV-URL. Bij Nextcloud leidt OciDeck dat pad zelf af — hier hoort alleen de server te staan.':
      'Ez teljes DAV URL-nek tűnik. Nextcloud esetén az OciDeck maga vezeti le ezt az útvonalat — ide csak a kiszolgáló való.',
  'Overnemen': 'Alkalmaz',
  'WebDAV is niet (goed) ingesteld — controleer de servergegevens bij Instellingen → Opslag.':
      'A WebDAV nincs (jól) beállítva — ellenőrizd a kiszolgáló adatait a Beállítások → Tárhely alatt.',
  'De git-repository is niet (goed) ingesteld — controleer server, eigenaar en repository bij Instellingen → Opslag.':
      'A git tároló nincs (jól) beállítva — ellenőrizd a kiszolgálót, a tulajdonost és a tárolót a Beállítások → Tárhely alatt.',
  'De servernaam van de forge bestaat niet, of is niet op te zoeken. Controleer de server-URL op een typefout.':
      'A forge kiszolgálójának neve nem létezik, vagy nem kereshető ki. Ellenőrizd, nincs-e elgépelés a kiszolgáló URL-jében.',
  'Deze forge heeft een privé- of LAN-adres. Markeer hem als vertrouwd intern bij Instellingen → Opslag.':
      'Ennek a forge-nak privát vagy LAN-címe van. Jelöld megbízható belsőként a Beállítások → Tárhely alatt.',
  'De forge is niet bereikbaar — controleer je verbinding en de server-URL.':
      'A forge nem érhető el — ellenőrizd a kapcsolatot és a kiszolgáló URL-jét.',
  'Aanmelden bij de forge mislukt. Controleer je token: het heeft leesrechten op de repository nodig, en schrijfrechten om op te slaan.':
      'A forge-ba való bejelentkezés nem sikerült. Ellenőrizd a tokent: olvasási jog kell a tárolóhoz, és írási jog a mentéshez.',
  'Niet gevonden in de repository — of je token mag het niet zien.':
      'Nem található a tárolóban — vagy a tokened nem láthatja.',
  'De forge gaf een fout. Probeer het later opnieuw.':
      'A forge hibát adott vissza. Próbáld újra később.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge bij Instellingen → Opslag?':
      'Ez a cím nem úgy válaszol, mint egy forge. Helyes a forge-típus a Beállítások → Tárhely alatt?',
  'Stel eerst een WebDAV-server in bij Instellingen → Opslag.':
      'Először állíts be egy WebDAV-kiszolgálót a Beállítások → Tárhely alatt.',
  'Nodig wanneer de forge op een privé- of thuisnetwerk draait. Zonder deze vlag weigert de beveiliging een privé-adres.':
      'Szükséges, ha a forge magán- vagy otthoni hálózaton fut. E jelölés nélkül a biztonsági ellenőrzés elutasít egy magáncímet.',
  'Vul server-URL, eigenaar en repository in':
      'Töltsd ki a kiszolgáló URL-jét, a tulajdonost és a tárolót',
  'de standaardbranch heet': 'az alapértelmezett ág neve',
  'die wordt voortaan gebruikt': 'mostantól az lesz használva',
  'de repository is nog leeg; de eerste opslag vult hem':
      'a tároló még üres; az első mentés tölti fel',
  'let op: dit token mag alleen lezen, dus opslaan zal mislukken':
      'figyelem: ez a token csak olvashat, így a mentés meg fog hiúsulni',
  'Aanmelden mislukt — controleer het token. Het heeft leesrechten op de repository nodig, en schrijfrechten om te kunnen opslaan.':
      'A bejelentkezés nem sikerült — ellenőrizd a tokent. Olvasási jog kell a tárolóhoz, és írási jog a mentéshez.',
